import SwiftUI
struct TodayView:View {
 @EnvironmentObject var store:AppStore;@EnvironmentObject var cal:CalendarManager;@EnvironmentObject var notes:NotificationManager;@StateObject var prayers=PrayerManager();@State var alert=false
 var body:some View{NavigationStack{VStack{HStack{Button("Start My Day"){cal.loadToday();prayers.request();store.generateDay(calendarBlocks:cal.todayBlocks,prayerBlocks:prayers.blocks);Task{await notes.schedule(store.schedule)}}.buttonStyle(.borderedProminent);Button("I'm Late 15 Mins"){store.late15();alert=true;Task{await notes.schedule(store.schedule)}}.buttonStyle(.bordered)}.padding()
 if store.schedule.isEmpty{ContentUnavailableView("Your day is ready to plan",systemImage:"sparkles",description:Text("Flexible work starts exactly 10 minutes after Start My Day."))}else{List(store.schedule){b in HStack{RoundedRectangle(cornerRadius:3).fill(color(b)).frame(width:6,height:44);VStack(alignment:.leading){Text(b.title).font(.headline);Text("\(b.start.formatted(date:.omitted,time:.shortened)) – \(b.end.formatted(date:.omitted,time:.shortened))").font(.caption).foregroundStyle(.secondary)};Spacer();if b.locked{Image(systemName:"lock.fill")}}}.listStyle(.plain)}}.navigationTitle("Alsagier").toolbar{Text("By Softfm").font(.caption)}.task{prayers.request()}.alert("Schedule updated",isPresented:$alert){Button("OK",role:.cancel){}}}}
 func color(_ b:ScheduleBlock)->Color{if let id=b.projectID,let p=store.projects.first(where:{$0.id==id}){return p.color.color};switch b.kind{case .calendar:return .gray;case .prayer:return .green;case .habit:return .purple;case .call:return .orange;case .email:return .blue;case .task:return .indigo}}
}